async function loseAck(page, path, operation) { await page.evaluate(({ path, operation }) => { const original = window.fetch.bind(window); let once = true; window.fetch = async (input, init) => { const request = new Request(input instanceof Request ? input.clone() : new URL(String(input), location.href), init); let body; if (once && request.method === 'POST' && new URL(request.url).pathname === path) body = await request.clone().text(); const lose = body && (!operation || JSON.parse(body).operation === operation); const response = await original(input, init); if (lose && response.status === 200) { once = false; window.__advisoryLostAck = { body, status: response.status }; await response.body?.cancel(); throw new TypeError('SYNTHETIC committed advisory acknowledgement lost'); } return response; }; }, { path, operation }); }
async function holdBuyerAck(page, pathname) {
  await page.evaluate(pathname => { const original = window.fetch.bind(window); let once = true; window.__heldBuyerAck = false; window.fetch = async (input, init) => { const request = new Request(input instanceof Request ? input.clone() : new URL(String(input), location.href), init), response = await original(input, init); if (once && request.method === 'POST' && new URL(request.url).pathname === pathname && response.status === 200) { once = false; window.__heldBuyerAck = true; await new Promise(resolve => { window.__releaseBuyerAck = resolve; }); } return response; }; }, pathname);
}
async function switchWhileBuyerAckHeld(page) {
  await expect.poll(() => page.evaluate(() => window.__heldBuyerAck)).toBe(true);
  const invalid = createHash('sha256').update(randomUUID()).digest('base64url'); secretValues.add(invalid);
  await page.evaluate(invalid => { window.__staleBuyerPacket = false; window.__buyerRaceObserver?.disconnect(); window.__buyerRaceObserver = new MutationObserver(() => { if (location.hash === '#grant=' + invalid && [...document.querySelectorAll('h2')].some(node => node.textContent === 'SYNTHETIC public decision packet')) window.__staleBuyerPacket = true; }); window.__buyerRaceObserver.observe(document.body, { subtree: true, childList: true, characterData: true }); location.hash = 'grant=' + invalid; }, invalid);
  const room = page.getByTestId('sales-buyer-room'); await expect(room.getByRole('heading', { name: 'SYNTHETIC public decision packet', exact: true })).toHaveCount(0);
  await page.evaluate(() => window.__releaseBuyerAck());
  await expect(room.getByText('Diese Mappe ist aktuell nicht verfügbar.', { exact: false })).toBeVisible();
  assert.equal(await page.evaluate(() => window.__staleBuyerPacket), false, 'A completed request must not show the old packet under a different link');
  await page.evaluate(token => { window.__buyerRaceObserver.disconnect(); location.hash = 'grant=' + token; }, buyerToken);
  await expect(room.getByRole('heading', { name: 'SYNTHETIC public decision packet', exact: true })).toBeVisible();
}
